INSERT INTO messages (id, channel_id, author, text, created_at) VALUES ('msg_seed_13', 'group:launch-week', 'ship', 'I will watch every deploy and the Sentry error rate on the site and the form endpoint. I interrupt you for site down, checkout failing or a security issue, nothing else.', '2026-10-29T11:14:00.000Z');
INSERT INTO messages (id, channel_id, author, text, created_at) VALUES ('msg_seed_14', 'group:launch-week', 'scout', 'I will track stars, referrers and any mention of Tidyform each morning and flag anything that is moving. A sudden spike in traffic from one source is the one thing I would flag the same day.', '2026-10-29T11:17:00.000Z');
INSERT INTO messages (id, channel_id, author, text, created_at) VALUES ('msg_seed_15', 'group:launch-week', 'cos', 'I will fold both into each evening handover and keep tonight''s list inside your window.', '2026-10-29T11:20:00.000Z');
