INSERT INTO messages (id, channel_id, author, text, created_at, mentions_json) VALUES ('msg_seed_17', 'backroom:seed-support-ship', 'support', 'Heads up: when a customer reports a form that stops submitting, I will send you the page URL and the time they gave. Can you match it against Sentry before I reply?', '2026-10-29T12:04:00.000Z', '["ship"]');
INSERT INTO messages (id, channel_id, author, text, created_at) VALUES ('msg_seed_18', 'backroom:seed-support-ship', 'ship', 'Yes. Send the URL and the timestamp and I will search errors in that minute. If I find a match I will tell you the cause in one line so your reply can be specific.', '2026-10-29T12:06:00.000Z');
INSERT INTO memories (id, agent, text, source, created_at) VALUES ('mem_seed_01', 'cos', 'Founder works Mon-Sat 09:00-18:00 at a day job. Founder hours are Mon-Sat 19:00-23:00 and Sun 10:00-16:00. Handover lands 15 minutes before the window.', 'seed: workspace setup', '2026-10-29T09:00:00.000Z');
INSERT INTO memories (id, agent, text, source, created_at) VALUES ('mem_seed_02', 'revenue', 'Tidyform costs $12/mo and Quillbill $29/mo. Both are connected to Stripe sandbox data only.', 'seed: workspace setup', '2026-10-29T09:00:00.000Z');
INSERT INTO memories (id, agent, text, source, created_at) VALUES ('mem_seed_03', 'support', 'The support inbox is jedionchain@gmail.com. Replies go out only after the founder approves the exact text.', 'seed: workspace setup', '2026-10-29T09:00:00.000Z');
INSERT INTO memories (id, agent, text, source, created_at) VALUES ('mem_seed_04', 'ship', 'The Tidyform repository is CipherKuma/tidyform and production errors are reported to Sentry.', 'seed: workspace setup', '2026-10-29T09:00:00.000Z');
INSERT INTO memories (id, agent, text, source, created_at) VALUES ('mem_seed_05', 'scout', 'Growth signals to track for Tidyform: GitHub stars, repository traffic referrers, competitor pricing pages.', 'seed: workspace setup', '2026-10-29T09:00:00.000Z');
INSERT INTO standing_orders (id, agent, text, created_at) VALUES ('so_seed_01', 'cos', 'Keep tonight''s plan to about 80 percent of the founder window. Leave room for the unexpected.', '2026-10-29T09:00:00.000Z');
